namespace sv_842a0487c25a47e4abb19fb5cd3be4bb.Services;

public enum Theme
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service that holds per-circuit theme state.
/// In Interactive Server mode, "scoped" = per circuit, so each user/tab gets independent state.
/// The circuit persists across enhanced navigations, keeping theme stable without page reload.
/// </summary>
public class ThemeService
{
    public Theme CurrentTheme { get; private set; } = Theme.System;
    public string AccentColor { get; private set; } = "#0d6efd";

    public event Action? OnChange;

    public void SetTheme(Theme theme)
    {
        if (CurrentTheme == theme) return;
        CurrentTheme = theme;
        OnChange?.Invoke();
    }

    public void SetAccentColor(string color)
    {
        if (AccentColor == color) return;
        AccentColor = color;
        OnChange?.Invoke();
    }

    public void SetPreferences(Theme theme, string accentColor)
    {
        var changed = CurrentTheme != theme || AccentColor != accentColor;
        CurrentTheme = theme;
        AccentColor = accentColor;
        if (changed) OnChange?.Invoke();
    }
}

@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService

<span class="theme-indicator" style="color: @ThemeService.AccentColor;" title="Current theme">
    @GetThemeIcon() @ThemeService.CurrentTheme
</span>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleThemeChanged;
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private string GetThemeIcon() => ThemeService.CurrentTheme switch
    {
        Theme.Light => "☀️",
        Theme.Dark => "🌙",
        _ => "💻"
    };

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

@page "/settings"
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="mb-3">
    <label class="form-label">Theme</label>
    <select class="form-select" style="max-width: 200px;"
            value="@ThemeService.CurrentTheme"
            @onchange="OnThemeSelected">
        @foreach (var t in Enum.GetValues<Theme>())
        {
            <option value="@t">@t</option>
        }
    </select>
</div>

<div class="mb-3">
    <label class="form-label">Accent Color</label>
    <input type="color" class="form-control form-control-color"
           value="@ThemeService.AccentColor"
           @onchange="OnAccentChanged" />
</div>

<div class="mt-4 p-3 border rounded" style="border-color: @ThemeService.AccentColor !important;">
    <strong>Preview:</strong> Current theme is <em>@ThemeService.CurrentTheme</em>
    with accent <span style="color: @ThemeService.AccentColor;">@ThemeService.AccentColor</span>
</div>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleThemeChanged;
    }

    private void OnThemeSelected(ChangeEventArgs e)
    {
        if (Enum.TryParse<Theme>(e.Value?.ToString(), out var theme))
        {
            ThemeService.SetTheme(theme);
        }
    }

    private void OnAccentChanged(ChangeEventArgs e)
    {
        ThemeService.SetAccentColor(e.Value?.ToString() ?? "#0d6efd");
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

